L={'A':[7,9,6,8],'B':[5,8,9,3],'C':[9,8,6,2]}
def ab(order):
    al=-1e9;n=0;best=-1e9
    for k in order:
        b=1e9;v=1e9
        for x in L[k]:
            n+=1;v=min(v,x);b=min(b,v)
            if al>=b:break
        best=max(best,v);al=max(al,best)
    return best,n
